// Proposed replacements for the two origin claims. Not applied to the store.
// Same primitive vocabulary and 100-unit grid as glyphs.cjs.
const n = (v) => Math.round(v * 100) / 100;
const C = (x, y, r) => ['c', n(x), n(y), n(r)];
const E = (x, y, rx, ry, rot = 0) => ['e', n(x), n(y), n(rx), n(ry), rot];
const L = (x1, y1, x2, y2) => ['l', n(x1), n(y1), n(x2), n(y2)];
const RR = (x, y, w, h, r) => ['rr', n(x), n(y), n(w), n(h), n(r)];
const D = (d) => ['d', d];
const DOT = (x, y, r) => ['dot', n(x), n(y), n(r)];
const A = (x, y, r, a0, a1) => ['a', n(x), n(y), n(r), a0, a1];
const FD = (d) => ['fd', d];
const BG = (d) => ['bg', d];

// Rounded rectangle at any rotation, with optional per-corner radii
// ordered top-left, top-right, bottom-right, bottom-left.
function rrot(cx, cy, w, h, deg, radii) {
  const a = (deg * Math.PI) / 180, ca = Math.cos(a), sa = Math.sin(a);
  const hw = w / 2, hh = h / 2;
  const P = (dx, dy) => [cx + dx * ca - dy * sa, cy + dx * sa + dy * ca];
  const pts = [P(-hw, -hh), P(hw, -hh), P(hw, hh), P(-hw, hh)];
  const rr = Array.isArray(radii) ? radii : [radii, radii, radii, radii];
  const sub = (p, q) => [p[0] - q[0], p[1] - q[1]];
  const len = (v) => Math.hypot(v[0], v[1]);
  const unit = (v) => { const l = len(v); return [v[0] / l, v[1] / l]; };
  const step = (p, v, k) => [p[0] + v[0] * k, p[1] + v[1] * k];
  const fmt = (p) => n(p[0]) + ' ' + n(p[1]);
  let d = '';
  for (let i = 0; i < 4; i++) {
    const prev = pts[(i + 3) % 4], cur = pts[i], next = pts[(i + 1) % 4];
    const r = Math.min(rr[i], len(sub(cur, prev)) / 2, len(sub(next, cur)) / 2);
    const p1 = step(cur, unit(sub(cur, prev)), -r);
    const p2 = step(cur, unit(sub(next, cur)), r);
    d += (i ? ' L' : 'M') + fmt(p1) + ' Q' + fmt(cur) + ' ' + fmt(p2);
  }
  return d + ' Z';
}

